const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={samples:[],jobs:[],profiles:[],notebookPresets:[],activeProfileId:null,name:'Mi letra',route:'home',capture:'template',review:[],draft:restoreDraft(),layout:null,page:0};
let busy=false,processing=false,workerSeq=0,toastTimer,previewTimer,cropImage,cropRect,installPrompt;const requests=new Map(),worker=new Worker('./worker.mjs',{type:'module'});
worker.onmessage=({data})=>{const item=requests.get(data.id);if(!item)return;requests.delete(data.id);clearTimeout(item.timer);data.error?item.reject(Error(data.error)):item.resolve(data.result);};
worker.onerror=()=>{for(const item of requests.values()){clearTimeout(item.timer);item.reject(Error('El motor se detuvo. Vuelve a abrir Trazo.'));}requests.clear();};
function run(method,...args){return new Promise((resolve,reject)=>{const id=++workerSeq;requests.set(id,{resolve,reject,timer:setTimeout(()=>{requests.delete(id);reject(Error('La imagen tardó demasiado. Prueba con una foto más pequeña.'));},180000)});worker.postMessage({id,method,args});});}
const active=()=>profileSamples(state.samples,state.activeProfileId),trashed=()=>profileSamples(state.samples,state.activeProfileId,{trash:true}),selectedProfile=()=>state.profiles.find(p=>p.id===state.activeProfileId),id=()=>crypto.randomUUID?.()||Date.now()+'-'+Math.random().toString(36).slice(2);
function profileBar(){return '<section class="profile-bar" aria-label="Biblioteca de escritura"><label>Biblioteca activa<select data-profile-select>'+state.profiles.map(p=>'<option value="'+esc(p.id)+'" '+(p.id===state.activeProfileId?'selected':'')+'>'+esc(p.name)+'</option>').join('')+'</select></label><p class="fine">'+active().length+' muestras · '+(state.activeProfileId.startsWith('personal-uniforme-')?'Una forma por carácter; sin alternancias.':'Se usa solo esta biblioteca.')+'</p><button class="btn" data-import-library>Importar biblioteca</button></section>';}
async function persistProfiles(){await setSetting('profiles',state.profiles);await setSetting('activeProfileId',state.activeProfileId);}
async function selectProfile(profileId){if(!state.profiles.some(p=>p.id===profileId))throw Error('Biblioteca no disponible.');if($('#pageText'))readDraft();clearTimeout(previewTimer);++layoutRequest;state.activeProfileId=profileId;state.name=selectedProfile().fontName;state.layout=null;state.page=0;await setSetting('activeProfileId',profileId);render();}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),6500);}
async function action(button,fn){if(button?.disabled)return;const old=button?.textContent;if(button){button.disabled=true;button.textContent='Un momento…';}try{await fn();}catch(e){toast(e.message||'No se pudo completar.');const error=$('#dialogError');if(error)error.textContent=e.message;}finally{if(button?.isConnected){button.disabled=false;button.textContent=old;}}}
