  $('#app').innerHTML=({home:homeView,letter:letterView,pages:pagesView,maps:mapsView,docs:docsView,drawings:drawingsView,settings:settingsView})[state.route]();$('#app').setAttribute('aria-busy','false');bindCommon();({home:bindHome,letter:bindLetter,pages:bindPages,maps:bindMaps,docs:bindDocs,drawings:bindDrawings,settings:bindSettings})[state.route]();
