function heading(kicker,title,intro,buttons=''){return `<div class="heading"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1><p class="intro">${intro}</p></div>${buttons?`<div class="actions">${buttons}</div>`:''}</div>`;}
function homeView(){const c=coverage(active()),unique=new Set(active().map(s=>s.label)).size;return heading('Tu estudio personal','Tu letra ya está aquí.','Escribe, organiza tus ideas y prepara tus hojas con la caligrafía que enviaste.')+profileBar()+`<div class="grid-2"><section class="card"><div class="section-top"><h2>Escribe como tú.</h2><span class="pill">Letra incluida</span></div><canvas id="homeInkPreview" class="personal-home-preview" width="900" height="240" aria-label="Ejemplo con tu letra activa"></canvas><p class="fine">Natural alterna 2–3 formas revisadas de cada letra, con bordes suavizados y signos más finos. Uniforme usa una sola forma por carácter. Original y Optimizada conservan todas tus variantes.</p><div class="actions"><button class="btn primary" data-go="pages">Escribir una página →</button><button class="btn" data-go="letter">Ver mi letra</button></div></section><section class="card"><h2>Ideas que se conectan.</h2><p class="intro">Mapas conceptuales, mapas mentales, diagramas de flujo, jerarquías y líneas de tiempo. Edita cada idea, conecta y organiza.</p><div class="actions"><button class="btn primary" data-go="maps">Crear un mapa →</button></div><div class="metrics"><div><span class="metric-number">${unique}</span><span class="metric-label">Caracteres activos</span></div><div><span class="metric-number">${active().length}</span><span class="metric-label">Formas de letra</span></div><div><span class="metric-number">5 mm</span><span class="metric-label">Cuadrícula ajustable</span></div></div></section></div><section class="card map-shortcut"><div><h3>Tu estudio también en Android</h3><p class="fine">Tu letra y el editor van incluidos. Guarda copias de tus mapas y bibliotecas para llevarlos a otro dispositivo.</p></div>${globalThis.TrazoNative?'<span class="pill">App sin conexión</span>':'<a class="btn" href="./descargas/Trazo.apk" download>Descargar APK</a>'}</section>`;}
function docsView(){return heading('Tareas / Hoja Oficio','Tu tarea completa, con tu letra.','Escribe o pega la tarea en el formato Trazo: títulos, datos y resolución, fórmulas y coordenadas. Revisa cada cara de la hoja y descarga el PDF.')+profileBar()+'<div id="docEditor"><p class="loading">Preparando tus tareas…</p></div>';}
async function bindDocs(){const root=$('#docEditor');try{const dispose=await mountDocuments(root,{samples:active(),toast});if(root.isConnected)disposeMapView=dispose;else dispose();}catch(e){if(root.isConnected)root.innerHTML='<p class="error">'+esc(e.message)+'</p>';}}
