async function updatePreview(){if(!$('#pageText'))return;const request=++layoutRequest;readDraft();try{const layout=await run('layoutText',state.draft.text,active(),state.draft);if(request!==layoutRequest||!$('#pageCanvas'))return;state.layout=layout;state.page=Math.min(state.page,Math.max(0,layout.pages.length-1));$('#pageError').textContent=layout.missing.length?'Faltan muestras para: '+layout.missing.join(' ')+' · Añádelas en Mi letra.':'';paintPage();}catch(e){if(request!==layoutRequest||!$('#pageError'))return;state.layout=null;$('#pageError').textContent=e.message;paintPage();}}
function paintPage(){const c=$('#pageCanvas');if(!c)return;const d=state.draft,scale=3;c.width=Math.round(d.width*scale);c.height=Math.round(d.height*scale);const ctx=c.getContext('2d');ctx.fillStyle=d.paperColor;ctx.fillRect(0,0,c.width,c.height);ctx.scale(scale,scale);ctx.lineJoin='round';for(const guide of paperGuides(d)){ctx.strokeStyle=guide.color;ctx.lineWidth=guide.margin?.5*25.4/72:.35*25.4/72;ctx.beginPath();ctx.moveTo(guide.x1,guide.y1);ctx.lineTo(guide.x2,guide.y2);ctx.stroke();}
  const entries=state.layout?.pages[state.page];if(entries?.length){for(const item of entries){ctx.fillStyle=item.color||d.ink;ctx.beginPath();for(const p of item.paths){p.forEach(([x,y],i)=>{const xx=item.x+x*item.scale,yy=item.y-y*item.scale;i?ctx.lineTo(xx,yy):ctx.moveTo(xx,yy);});ctx.closePath();}ctx.fill('nonzero');if(item.strokeWidth){ctx.strokeStyle=item.color||d.ink;ctx.lineWidth=item.strokeWidth*item.scale;ctx.stroke();}}}else{ctx.fillStyle='#8598aa';ctx.textAlign='center';ctx.font='4px sans-serif';ctx.fillText(active().length?'Escribe un texto para ver tu página.':'Añade tus muestras en «Mi letra».',d.width/2,40);}$('#pageCount').textContent=state.layout?.pages.length?`Página ${state.page+1} de ${state.layout.pages.length}`:'Tu vista previa';$('#prevPage').disabled=!state.layout||state.page===0;$('#nextPage').disabled=!state.layout||state.page>=state.layout.pages.length-1;}
