function drawJobs(){if(!$('#jobs'))return;$('#jobStatus').textContent=state.jobs.filter(j=>j.status==='pending'||j.status==='running').length+' pendientes';$('#jobs').innerHTML=state.jobs.length?state.jobs.slice().reverse().map(j=>`<article class="job">${j.thumb?`<img src="${j.thumb}" alt="Miniatura de ${esc(j.name)}">`:'<span class="muted">▧</span>'}<div><p class="job-name">${esc(j.name)}</p><p class="fine">${esc({pending:'En cola',running:'Procesando…',done:'Lista',error:'No se pudo procesar'}[j.status])} · ${esc({original:'Original',clean:'Limpio',vector:'Contornos'}[j.mode])}</p>${j.error?`<p class="error">${esc(j.error)}</p>`:''}<div class="actions">${j.status==='done'?`<button class="btn small" data-jobpdf="${j.id}">PDF A4</button><button class="btn small" data-jobfile="${j.id}">${j.mode==='vector'?'SVG':j.mode==='original'?'Original':'PNG limpio'}</button>`:''}${j.status==='error'?`<button class="btn small" data-jobretry="${j.id}">Reintentar</button>`:''}</div></div></article>`).join(''):`<div class="empty"><div class="empty-char">✎</div><h3>Tu próximo dibujo empieza aquí</h3><p>Añade hasta 10 imágenes por lote.</p></div>`;$$('[data-jobpdf]').forEach(b=>b.onclick=()=>action(b,async()=>{const j=state.jobs.find(x=>x.id===b.dataset.jobpdf);await saveFile(j.pdf,cleanName(j.name)+'.pdf');toast('PDF listo para guardar.');}));$$('[data-jobfile]').forEach(b=>b.onclick=()=>action(b,async()=>{const j=state.jobs.find(x=>x.id===b.dataset.jobfile);await saveFile(j.output,j.mode==='original'?j.name:cleanName(j.name)+(j.mode==='vector'?'.svg':'.png'));toast('Archivo listo para guardar.');}));$$('[data-jobretry]').forEach(b=>b.onclick=async()=>{const j=state.jobs.find(x=>x.id===b.dataset.jobretry);j.status='pending';await putMany('jobs',[j]);processQueue();});}
const cleanName=name=>name.replace(/\.[^.]+$/,'').replace(/[^\p{L}\p{N}._ -]/gu,'_').slice(0,80)||'Trazo-dibujo';
async function addDrawings(files){if(files.length>10)throw Error('Añade como máximo 10 imágenes por lote.');if(files.some(f=>f.size>20*1024*1024))throw Error('Alguna imagen supera 20 MB.');const mode=$('[name=drawingMode]:checked')?.value||'original',threshold=+($('#drawingThreshold')?.value||180),jobs=files.map(file=>({id:id(),name:file.name,source:file,mode,threshold,status:'pending',created:Date.now()}));await putMany('jobs',jobs);state.jobs.push(...jobs);drawJobs();processQueue();}
async function processQueue(){if(processing)return;processing=true;globalThis.TrazoNative?.setProcessing(true);let wake;try{wake=await navigator.wakeLock?.request('screen');}catch{}try{for(const j of state.jobs.filter(j=>j.status==='pending')){j.status='running';await putMany('jobs',[j]);drawJobs();try{const canvas=await imageCanvas(j.source,j.mode==='vector'?1200:2400),w=canvas.width,h=canvas.height;let paths=null;if(j.mode!=='original'){const ctx=canvas.getContext('2d'),im=ctx.getImageData(0,0,w,h),mask=new Uint8Array(w*h);for(let i=0;i<mask.length;i++){const k=i*4,black=(.2126*im.data[k]+.7152*im.data[k+1]+.0722*im.data[k+2])<j.threshold;mask[i]=black?1:0;im.data[k]=im.data[k+1]=im.data[k+2]=black?0:255;}ctx.putImageData(im,0,0);if(j.mode==='vector'){paths=await run('traceMask',mask,w,h,.5);if(!paths.length)throw Error('No se encontraron contornos oscuros. Ajusta el umbral y vuelve a añadir la imagen.');}}
      const png=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!png)throw Error('No se pudo preparar la imagen.');j.pdf=await drawingPDF(png,w,h,paths);j.output=j.mode==='original'?j.source:j.mode==='vector'?new Blob([`<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}"><path fill="black" fill-rule="nonzero" d="${svgPaths(paths)}"/></svg>`],{type:'image/svg+xml'}):png;const t=document.createElement('canvas');t.width=110;t.height=Math.round(110*h/w);t.getContext('2d').drawImage(canvas,0,0,t.width,t.height);j.thumb=t.toDataURL('image/png');j.status='done';delete j.error;}catch(e){j.status='error';j.error=e.message;}await putMany('jobs',[j]);drawJobs();}}catch(e){toast('No se pudo guardar la cola: '+e.message);}finally{processing=false;globalThis.TrazoNative?.setProcessing(false);try{await wake?.release();}catch{}if(state.jobs.some(j=>j.status==='pending'))setTimeout(processQueue,300);}}
